// Turns the form answers into one row for the Events tab. The window length is capped by maxWindowHours.
const cfg = $('Set Desk Configuration').first().json;
const num = (v, d) => { const n = Number(v); return Number.isFinite(n) && n > 0 ? n : d; };

// Each line of the search query is sent to YouTube exactly as typed
const queries = [...new Set(String(cfg['Search query'] || '').split(/\r?\n/).map(q => q.trim()).filter(Boolean))];
if (!queries.length) throw new Error('Add a search query.');
const hours = Math.min(num(cfg['Hours to monitor'], num(cfg.defaultWindowHours, 6)), num(cfg.maxWindowHours, 24));
const now = new Date();

return [{ json: {
  'Event ID': 'evt-' + now.getTime().toString(36),
  'Query Name': String(cfg['Query name'] || '').trim() || queries[0],
  'Search Queries': queries.join('\n'),
  'Opened At': now.toISOString(),
  'Ends At': new Date(now.getTime() + hours * 3600000).toISOString(),
  'Active': 'yes',
  'Status': 'Monitoring',
  'Last Run At': '',
  'Videos Logged': 0,
  'Candidates': 0,
  'Credits Used': 0,
  'Closed At': ''
} }];

