// Picks the open events from the Events tab, plans one search job per query and format, and marks
// events whose window has ended (or that an editor set to Active = no) for closing and a wrap-up.
// The plan is kept in workflow static data for this run only and removed again at the end.
const cfg = $('Set Desk Configuration').first().json;
const state = $getWorkflowStaticData('global');
state.runQuota = null;   // transient: remaining daily credits, set while fetching
state.runAbort = false;  // transient: set after a fatal API error so remaining searches are skipped

const num = (v, d) => { const n = Number(v); return Number.isFinite(n) ? n : d; };
const list = v => [...new Set(String(v || '').split(/[,;\n]+/).map(s => s.trim()).filter(Boolean))];
// n8n reports editor runs as 'test' (older versions: 'manual'); the manual trigger check is a second signal
let manual = ['test', 'manual'].includes($execution.mode);
try { if ($('When Manually Triggered').isExecuted) manual = true; } catch (e) { /* node not executed */ }

const now = Date.now();
const formats = list(cfg.formats).map(f => f.toLowerCase()).filter(f => f === 'video' || f === 'shorts');
if (!formats.length) throw new Error('Set "formats" in "Set Desk Config" to video, shorts, or both.');
const maxQueries = Math.max(1, num(cfg.maxQueriesPerEvent, 4));
const maxCredits = Math.max(1, num(cfg.maxCreditsPerRun, 12));
const firstRunWindow = ['hour', 'today'].includes(cfg.firstRunUploadDate) ? cfg.firstRunUploadDate : 'today';

const open = [], closing = [], problems = [];
for (const item of $('Fetch Events From Sheet').all()) {
  const r = item.json || {};
  const id = String(r['Event ID'] || '').trim();
  if (!id || String(r['Status'] || '').trim().toLowerCase() === 'closed') continue;
  const queries = [...new Set(String(r['Search Queries'] || '').split(/\r?\n/).map(q => q.trim()).filter(Boolean))];
  const opened = Date.parse(r['Opened At']);
  let ends = Date.parse(r['Ends At']);
  if (isNaN(ends)) ends = (isNaN(opened) ? now : opened) + num(cfg.defaultWindowHours, 6) * 3600000;
  const ev = {
    id, name: String(r['Query Name'] || queries[0] || id), queries,
    openedAt: String(r['Opened At'] || ''), endsAt: new Date(ends).toISOString(), lastRunAt: String(r['Last Run At'] || ''),
    videosLogged: num(r['Videos Logged'], 0), candidates: num(r['Candidates'], 0), creditsUsed: num(r['Credits Used'], 0)
  };
  if (String(r['Active'] ?? 'yes').trim().toLowerCase() === 'no' || now >= ends) { closing.push(ev); continue; }
  if (!queries.length) { problems.push(ev.name + ': no search query in the Events tab, so nothing was searched'); continue; }
  open.push(ev);
}

// Each search query is used exactly as entered. Normal runs use the last-hour filter; runs after a
// gap (missed or failed runs) widen it once to "today". Dedupe removes the overlap.
const perEvent = open.map(ev => {
  const queries = ev.queries.slice(0, maxQueries);
  if (ev.queries.length > maxQueries) problems.push(ev.name + ': ' + (ev.queries.length - maxQueries) + ' search queries skipped because maxQueriesPerEvent is ' + maxQueries);
  const last = Date.parse(ev.lastRunAt);
  const uploadDate = isNaN(last) ? firstRunWindow : ((now - last) / 60000 > 50 ? 'today' : 'hour');
  // Paging stops once a page reaches videos older than this (last run minus 5 minutes of overlap)
  const since = new Date(isNaN(last) ? now - (uploadDate === 'today' ? 24 : 1) * 3600000 : last - 5 * 60000).toISOString();
  return queries.flatMap(query => formats.map(format => ({ eventId: ev.id, query, format, uploadDate, since })));
});

// Interleave events so a credit cap never starves one event, then apply the cap
let jobs = [];
for (let i = 0; perEvent.some(a => i < a.length); i++) for (const a of perEvent) if (i < a.length) jobs.push(a[i]);
const dropped = jobs.slice(maxCredits);
jobs = jobs.slice(0, maxCredits);
for (const d of dropped) problems.push('"' + d.query + '" (' + d.format + '): skipped because maxCreditsPerRun is too low for all queries');
const maxPages = jobs.length ? Math.max(1, Math.min(num(cfg.maxPagesPerSearch, 2), Math.floor(maxCredits / jobs.length))) : 0;

state.runPlan = { open, closing, problems, manual, droppedEvents: [...new Set(dropped.map(d => d.eventId))] };

if (!jobs.length) {
  if (!closing.length && !problems.length && !manual) { delete state.runPlan; return []; }  // nothing open: end quietly
  // Nothing to search, but something to report: one marker item passes through the loop
  return [{ json: { marker: true, skipped: true, skipReason: 'nothing to search' } }];
}
return jobs.map(j => ({ json: { ...j, maxPages, pages: 0, posts: [], token: '' } }));

// Entry point for every page request (first page and follow-up pages).
// Marks the job as skipped when the quota is low or a fatal API error already happened in this run.
const cfg = $('Set Desk Configuration').first().json;
const state = $getWorkflowStaticData('global');
const job = { ...$json };
job.pages = job.pages || 0;
job.posts = job.posts || [];
job.token = job.token || '';
const minQuota = Number(cfg.minQuotaRemaining);
if (job.marker) {
  job.skipped = true;
} else if (state.runAbort) {
  job.skipped = true;
  job.skipReason = 'skipped after a fatal API error earlier in this run';
} else if (typeof state.runQuota === 'number' && Number.isFinite(minQuota) && state.runQuota < minQuota) {
  job.skipped = true;
  job.skipReason = 'skipped because the remaining daily quota (' + state.runQuota + ') is below ' + minQuota;
}
return [{ json: job }];

// Reads one page of results, keeps the fields the desk needs, and decides whether to fetch another page.
const cfg = $('Set Desk Configuration').first().json;
const state = $getWorkflowStaticData('global');
const job = { ...$('Prepare Search Page Request').last().json };
const res = $input.first().json || {};
const headers = res.headers || {};
const body = res.body;
const minQuota = Number(cfg.minQuotaRemaining);

const rem = headers['x-ratelimit-remaining'];
const remaining = rem !== undefined && rem !== '' && Number.isFinite(Number(rem)) ? Number(rem) : null;
if (remaining !== null) state.runQuota = remaining;

job.pages += 1;   // every answered page costs one credit
if (!body || !Array.isArray(body.results)) {
  job.failed = true;
  job.error = 'Unexpected response (no results array): ' + JSON.stringify(body || {}).slice(0, 200);
  job.more = false;
  return [{ json: job }];
}

const seen = new Set(job.posts.map(p => p.url));
for (const r of body.results) {
  if (!r || !r.url || seen.has(r.url)) continue;
  seen.add(r.url);
  job.posts.push({
    url: String(r.url),
    title: String(r.caption || '').slice(0, 300),   // caption is the video title on YouTube
    author: r.author ? String(r.author) : '',
    author_id: r.author_id ? String(r.author_id) : '',
    posted_at: r.posted_at || null
  });
}

// Results come newest first. Once a page reaches videos older than the last run, there is nothing new further back.
const times = body.results.map(r => Date.parse(r && r.posted_at)).filter(t => !isNaN(t));
const reachedSince = times.length > 0 && Math.min(...times) <= Date.parse(job.since);
const token = body.next_pagination_token || '';
const quotaLow = remaining !== null && Number.isFinite(minQuota) && remaining < minQuota;
job.more = Boolean(token) && !reachedSince && job.pages < job.maxPages && !quotaLow;
// capped = older unseen videos may exist, but the page cap or quota stopped us
job.capped = Boolean(token) && !reachedSince && !job.more;
job.token = job.more ? token : '';
return [{ json: job }];

// Converts a failed request into a marker item so the loop continues and all problems are reported together.
// Parameter, auth, plan and rate-limit errors stop the remaining searches of this run.
const job = { ...$('Prepare Search Page Request').last().json };
const state = $getWorkflowStaticData('global');
const err = $input.first().json.error;
const message = (err && (err.message || err.description)) || (typeof err === 'string' ? err : JSON.stringify(err || {}));
const m = /\b(400|401|403|429|500|503)\b/.exec(String(message));
const status = m ? Number(m[1]) : null;
const hints = { 401: 'API key missing or revoked', 403: 'plan has no API access', 429: 'daily quota or per-minute limit reached', 400: 'invalid search parameter' };

job.failed = true;
job.statusCode = status;
job.error = (hints[status] ? hints[status] + ': ' : '') + String(message).slice(0, 250);
job.more = false;
if ([400, 401, 403, 429].includes(status)) state.runAbort = true;
return [{ json: job }];

// Merges all search results, drops videos already in the Footage Log, and gives every new video a
// rule-based category, score and reason. Rule labels are the fallback when AI is off or fails.
const cfg = $('Set Desk Configuration').first().json;
const state = $getWorkflowStaticData('global');
const plan = state.runPlan || { open: [], closing: [], problems: [], manual: false, droppedEvents: [] };
const num = (v, d) => { const n = Number(v); return Number.isFinite(n) ? n : d; };
const list = v => [...new Set(String(v || '').split(/[,;\n]+/).map(s => s.trim()).filter(Boolean))];
const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const escRe = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
// Whole-word match, so "tv" does not match "tvshow" and "news" does not match "newsletter"
const findTerm = (text, terms) => terms.find(t => t && new RegExp('(^|[^\\p{L}\\p{N}])' + escRe(t) + '($|[^\\p{L}\\p{N}])', 'u').test(text));
const videoId = url => { const m = /(?:[?&]v=|\/shorts\/|youtu\.be\/|\/live\/)([\w-]{3,})/.exec(String(url || '')); return m ? m[1] : String(url || '').trim(); };
const tokens = s => new Set(norm(s).replace(/[^\p{L}\p{N}\s]/gu, ' ').split(/\s+/).filter(w => w.length >= 3));
const jaccard = (a, b) => { if (a.size < 3 || b.size < 3) return 0; let i = 0; for (const w of a) if (b.has(w)) i++; return i / (a.size + b.size - i); };

const FOOTAGE = list(cfg.footageTerms).map(norm);
const NEWS = list(cfg.newsTerms).map(norm);
const COMMENT = list(cfg.commentaryTerms).map(norm);
const NEWS_CHANNELS = list(cfg.newsChannels).map(norm);
const SIM = num(cfg.copyTitleSimilarity, 0.8);

// Videos already logged (dedupe across runs), and earlier titles per event (copy detection)
const seen = new Set();
const earlier = {};
for (const it of $('Fetch Footage Log From Sheet').all()) {
  const r = it.json || {};
  const key = String(r['Video ID'] || '').trim() || videoId(r['Video URL']);
  if (!key) continue;
  seen.add(key);
  if (r['Event ID']) (earlier[r['Event ID']] = earlier[r['Event ID']] || []).push({ url: r['Video URL'], postedAt: String(r['Posted At'] || ''), tok: tokens(r['Title']) });
}

const evById = Object.fromEntries(plan.open.map(e => [e.id, e]));
const credits = {}, searched = new Set(), incomplete = new Set(plan.droppedEvents || []);
const problems = [...plan.problems];
let capped = 0;
const videos = [];
for (const it of $input.all()) {
  const j = it.json;
  if (j.marker || !j.eventId) continue;
  const ev = evById[j.eventId];
  searched.add(j.eventId);
  credits[j.eventId] = (credits[j.eventId] || 0) + (j.pages || 0);
  if (j.capped) capped++;
  if (j.failed || j.skipped) {
    incomplete.add(j.eventId);
    problems.push((ev ? ev.name : j.eventId) + ' / "' + j.query + '" (' + j.format + '): ' + (j.error || j.skipReason || 'request failed'));
  }
  if (!ev) continue;
  const QUERIES = ev.queries.map(q => [...tokens(q)]).filter(ws => ws.length);
  for (const p of j.posts || []) {
    const id = videoId(p.url);
    if (!id || seen.has(id)) continue;
    seen.add(id);
    const t = norm(p.title), ch = norm(p.author);
    const format = /\/shorts\//.test(p.url) ? 'shorts' : j.format;   // a video search can also return Shorts
    const footageHit = findTerm(t, FOOTAGE);
    // Query match: all words of one search query in the title (full), or at least one word (partial)
    const tt = tokens(p.title);
    const fullMatch = QUERIES.some(ws => ws.every(w => tt.has(w)));
    const partMatch = fullMatch || QUERIES.some(ws => ws.some(w => tt.has(w)));
    const newsHit = findTerm(t, NEWS) || (NEWS_CHANNELS.some(n => ch === n || ch.includes(n)) ? 'known news channel' : null);
    const commentHit = findTerm(t, COMMENT);
    let score = 40; const why = [];
    if (footageHit) { score += 25; why.push('footage term "' + footageHit + '"'); }
    if (fullMatch) { score += 15; why.push('matches the whole query'); }
    if (format === 'shorts') { score += 10; why.push('Short'); }
    if (!partMatch) { score -= 20; why.push('no query word in title'); }
    let category = 'unclear';
    if (newsHit) { category = 'news_reupload'; why.push('news signal "' + newsHit + '"'); }
    else if (commentHit) { category = 'commentary'; why.push('commentary term "' + commentHit + '"'); }
    else if (footageHit || (fullMatch && format === 'shorts')) category = 'eyewitness';
    if (category !== 'eyewitness') score = Math.min(score, 50);   // only eyewitness videos can reach the queue
    videos.push({
      videoId: id, url: p.url, title: p.title, author: p.author, authorId: p.author_id, postedAt: p.posted_at || '',
      format, query: j.query, eventId: ev.id, eventName: ev.name,
      category, score: Math.max(0, Math.min(100, score)), labeledBy: 'rules', reason: 'Rules: ' + (why.join(', ') || 'no signal'),
      tok: tokens(p.title), copyOf: ''
    });
  }
}

// Possible copies: a title very similar to an earlier upload for the same event (log or this run)
videos.sort((a, b) => String(a.postedAt).localeCompare(String(b.postedAt)));
for (let i = 0; i < videos.length; i++) {
  const v = videos[i];
  const prior = (earlier[v.eventId] || []).concat(videos.slice(0, i).filter(o => o.eventId === v.eventId).map(o => ({ url: o.url, postedAt: o.postedAt, tok: o.tok })));
  const match = prior.filter(o => !v.postedAt || !o.postedAt || o.postedAt <= v.postedAt).find(o => jaccard(v.tok, o.tok) >= SIM);
  if (match) v.copyOf = match.url;
}
videos.forEach((v, i) => { v.i = i; delete v.tok; });

// AI batch: the most promising videos first, capped by maxVideosForAi
const useAi = cfg.useAi === true || String(cfg.useAi).toLowerCase() === 'true';
const aiVideos = [...videos].sort((a, b) => b.score - a.score).slice(0, Math.max(0, num(cfg.maxVideosForAi, 40)));
const evLines = plan.open.filter(e => aiVideos.some(v => v.eventId === e.id))
  .map(e => '- ' + e.name + ' | search queries: ' + e.queries.join(' / '));
const prompt = String(cfg.aiRubric || '') +
  '\n\nEvents:\n' + evLines.join('\n') +
  '\n\nVideos (one JSON object per line):\n' +
  aiVideos.map(v => JSON.stringify({ i: v.i, event: v.eventName, title: v.title, channel: v.author, format: v.format, posted_at: v.postedAt })).join('\n') +
  '\n\nReturn only JSON in exactly this shape: {"items":[{"i":0,"category":"eyewitness","confidence":0.8,"reason":"short reason"}]}. ' +
  'One entry per video with the same "i", category one of eyewitness, news_reupload, commentary, unrelated, confidence between 0 and 1.';

if (videos.length > aiVideos.length && useAi) problems.push((videos.length - aiVideos.length) + ' videos were labeled by rules only because of maxVideosForAi');

return [{ json: {
  videos, prompt, sendToAi: useAi && aiVideos.length > 0 ? 'yes' : 'no',
  credits, searched: [...searched], incomplete: [...incomplete], capped, problems
} }];

// Applies valid AI labels (falls back to the rule label per video), decides what goes into the
// verification queue, and builds the rows for both tabs plus the data for the Telegram digest.
const cfg = $('Set Desk Configuration').first().json;
const state = $getWorkflowStaticData('global');
const plan = state.runPlan || { open: [], closing: [], problems: [], manual: false };
const run = $('Assess Video Relevance').first().json;
const num = (v, d) => { const n = Number(v); return Number.isFinite(n) ? n : d; };
const videos = JSON.parse(JSON.stringify(run.videos));   // copy, so the scored output stays unchanged
const problems = [...run.problems];
const CATS = ['eyewitness', 'news_reupload', 'commentary', 'unrelated'];

// Validate the AI output. Anything malformed keeps the rule label.
let aiRan = false;
try { aiRan = $('AI Classify Video Titles').isExecuted; } catch (e) { /* not executed */ }
if (aiRan) {
  const out = $('AI Classify Video Titles').first().json || {};
  const raw = out.text ?? out.response ?? out.output ?? '';
  const txt = typeof raw === 'string' ? raw : JSON.stringify(raw);
  let items = null;
  const a = txt.indexOf('{'), b = txt.lastIndexOf('}');
  if (a >= 0 && b > a) { try { const o = JSON.parse(txt.slice(a, b + 1)); if (Array.isArray(o.items)) items = o.items; } catch (e) { /* malformed */ } }
  if (!items) {
    const err = out.error ? ' (' + String(out.error.message || out.error).slice(0, 150) + ')' : '';
    problems.push('AI output missing or not valid JSON' + err + '. Rule labels were used.');
  } else {
    let bad = 0;
    for (const l of items) {
      const v = Number.isInteger(l && l.i) ? videos[l.i] : undefined;
      const conf = Number(l && l.confidence);
      if (!v || !CATS.includes(l.category) || !Number.isFinite(conf) || conf < 0 || conf > 1) { bad++; continue; }
      v.category = l.category;
      v.score = Math.round(conf * 100);
      v.labeledBy = 'ai';
      v.reason = String(l.reason || '').slice(0, 200);
    }
    if (bad) problems.push(bad + (bad === 1 ? ' AI label was' : ' AI labels were') + ' invalid, so the rule label was kept.');
  }
}

const minScore = num(cfg.minQueueScore, 60);
const nowIso = new Date().toISOString();
const queued = v => v.category === 'eyewitness' && v.score >= minScore;

const footageRows = videos.map(v => ({
  'Video ID': v.videoId, 'Video URL': v.url, 'Event ID': v.eventId, 'Query Name': v.eventName,
  'Status': queued(v) ? 'To verify' : 'Logged', 'Category': v.category, 'Confidence': v.score, 'Labeled By': v.labeledBy,
  'Reason': v.reason, 'Possible Copy Of': v.copyOf, 'Title': v.title, 'Channel': v.author, 'Channel ID': v.authorId,
  'Format': v.format, 'Posted At': v.postedAt, 'First Seen At': nowIso, 'Matched Query': v.query, 'Desk Notes': ''
}));

// New candidates per event, earliest upload first (the original is usually the earliest)
const candidates = {};
for (const v of videos.filter(queued)) (candidates[v.eventId] = candidates[v.eventId] || []).push(v);
for (const k of Object.keys(candidates)) candidates[k].sort((a, b) => String(a.postedAt).localeCompare(String(b.postedAt)));

// Event updates. "Last Run At" only moves forward when every search of the event succeeded,
// so the next run widens its window and catches up after a failure.
const eventRows = [];
const incomplete = new Set(run.incomplete);
const searchedEvents = new Set(run.searched);
for (const ev of plan.open) {
  if (!searchedEvents.has(ev.id)) continue;
  const mine = videos.filter(v => v.eventId === ev.id);
  const row = {
    'Event ID': ev.id,
    'Videos Logged': ev.videosLogged + mine.length,
    'Candidates': ev.candidates + mine.filter(queued).length,
    'Credits Used': ev.creditsUsed + (run.credits[ev.id] || 0)
  };
  if (!incomplete.has(ev.id)) row['Last Run At'] = nowIso;
  eventRows.push(row);
}

// Wrap-ups for closed windows, built from the Footage Log including the desk's status edits
const wrapups = [];
const logRows = $('Fetch Footage Log From Sheet').all().map(i => i.json || {});
for (const ev of plan.closing) {
  const rows = logRows.filter(r => r['Event ID'] === ev.id);
  const status = s => rows.filter(r => String(r['Status'] || '').toLowerCase() === s).length;
  const earliest = rows
    .filter(r => r['Category'] === 'eyewitness' && String(r['Status'] || '').toLowerCase() !== 'rejected' && !r['Possible Copy Of'])
    .sort((a, b) => String(a['Posted At']).localeCompare(String(b['Posted At'])))
    .slice(0, num(cfg.maxCandidatesPerEvent, 8))
    .map(r => ({ title: r['Title'], url: r['Video URL'], author: r['Channel'], postedAt: r['Posted At'], status: r['Status'] }));
  wrapups.push({
    name: ev.name, openedAt: ev.openedAt, total: rows.length, toVerify: status('to verify'),
    verified: status('verified'), rejected: status('rejected'), credits: ev.creditsUsed, earliest
  });
  eventRows.push({ 'Event ID': ev.id, 'Status': 'Closed', 'Active': 'no', 'Closed At': nowIso });
}

const creditsUsed = Object.values(run.credits).reduce((s, c) => s + c, 0);
if (run.capped) problems.push(run.capped + ' searches hit the page cap, so some older videos may be missing. Raise maxPagesPerSearch if this repeats.');
const summary = {
  runAt: nowIso, manual: plan.manual, openEvents: plan.open.map(e => e.name), candidates, wrapups, problems,
  newVideos: videos.length, creditsUsed, quotaRemaining: typeof state.runQuota === 'number' ? state.runQuota : null,
  footageRows, eventRows
};
delete state.runPlan;   // transient run data, not needed after this point
return [{ json: summary }];

