// Builds one Telegram digest per run (HTML parse mode, all text escaped) and splits it if it gets long.
// Returns nothing on quiet runs, so no empty messages are sent.
const s = $('Generate AI Labels and Rows').first().json;
const cfg = $('Set Desk Configuration').first().json;
const esc = t => String(t === null || t === undefined ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const hhmm = iso => (iso && !isNaN(Date.parse(iso))) ? new Date(iso).toISOString().slice(11, 16) : '?';
const MAX = Math.max(1, Number(cfg.maxCandidatesPerEvent) || 8);
const MAX_LEN = 3500;   // Telegram limit is 4096 characters

const lines = [];
for (const list of Object.values(s.candidates)) {
  lines.push('', '<b>' + esc(list[0].eventName) + '</b>: ' + list.length + ' new candidate' + (list.length === 1 ? '' : 's'));
  for (const v of list.slice(0, MAX)) {
    lines.push('• <a href="' + esc(v.url) + '">' + esc(v.title || '(untitled)') + '</a>');
    lines.push('   ' + esc(v.author || 'unknown channel') + ' | ' + (v.format === 'shorts' ? 'Short' : 'Video') + ' | posted ' + hhmm(v.postedAt) + ' UTC | '
      + v.score + '% (' + v.labeledBy + ')' + (v.copyOf ? ' | <b>possible copy</b>' : ''));
    if (v.reason) lines.push('   <i>' + esc(v.reason) + '</i>');
  }
  if (list.length > MAX) lines.push('+ ' + (list.length - MAX) + ' more in the Footage Log');
}
for (const w of s.wrapups) {
  lines.push('', '🏁 <b>Wrap-up: ' + esc(w.name) + '</b>');
  lines.push(w.total + ' videos logged. Desk status: ' + w.toVerify + ' to verify, ' + w.verified + ' verified, ' + w.rejected + ' rejected. Credits used: ' + w.credits + '.');
  if (w.earliest.length) {
    lines.push('<i>Earliest eyewitness candidates (likely originals):</i>');
    for (const e of w.earliest) lines.push('• ' + hhmm(e.postedAt) + ' UTC <a href="' + esc(e.url) + '">' + esc(e.title || '(untitled)') + '</a> (' + esc(e.author) + ', ' + esc(e.status) + ')');
  }
}
if (s.problems.length) {
  lines.push('', '<b>Problems in this run</b>');
  for (const p of s.problems.slice(0, 10)) lines.push('• ' + esc(p));
}

const quiet = lines.length === 0;
if (quiet && !s.manual) return [];
if (s.manual) {
  if (!s.openEvents.length && !s.wrapups.length) lines.push('', 'Manual test run. No open events. Open one with the "Open Event Window Form".');
  else if (quiet) lines.push('', 'Manual test run. Open events: ' + esc(s.openEvents.join(', ')) + '. ' + s.newVideos + ' new videos, none queued for verification.');
  else lines.push('', 'Manual test run.');
}
const sheet = String(cfg.sheetUrl || '').startsWith('http') ? '<a href="' + esc(cfg.sheetUrl) + '">Footage Log</a> | ' : '';
lines.push('', sheet + 'Credits this run: ' + s.creditsUsed + (s.quotaRemaining !== null ? ' | Daily quota left: ' + s.quotaRemaining : ''));

const header = '🎥 <b>Eyewitness desk</b> | ' + esc(s.runAt.slice(0, 16).replace('T', ' ')) + ' UTC';
const messages = [];
let chunk = header;
for (const line of lines) {
  if ((chunk + '\n' + line).length > MAX_LEN) { messages.push({ json: { chatId: cfg.telegramChatId, text: chunk } }); chunk = header + ' (cont.)'; }
  chunk += '\n' + line;
}
messages.push({ json: { chatId: cfg.telegramChatId, text: chunk } });
return messages;
